use serde_json::{json, Value};
use std::{fmt::Write, fs};
fn main() {
    let root = "/home/ubuntu/src/zopro-perf-work/factor-recoding";
    let result: Value = serde_json::from_slice(&fs::read(format!("{root}/result.json")).unwrap()).unwrap();
    let rows = result["rows"].as_array().unwrap();
    assert_eq!(rows.len(), 120);
    let mut summary = vec![];
    let mut table = String::new();
    for workload in ["uniform_full_width", "small_0_through_16383"] {
        let baseline = rows.iter().find(|r| r["workload"] == workload && r["width"] == 12 && r["strategy"] == "canonical").unwrap();
        for row in rows.iter().filter(|r| r["workload"] == workload && r["width"] == 12) {
            let terms = row["nonzero_terms"].as_u64().unwrap();
            let ratio = terms as f64 / baseline["nonzero_terms"].as_u64().unwrap() as f64;
            let windows: usize = row["groups"].as_array().unwrap().iter().map(|g| g["windows"].as_array().unwrap().len()).sum();
            writeln!(table,"| {workload} | {} | {terms} | {:.6} | {} | {windows} | {} |",row["strategy"].as_str().unwrap(),ratio,row["ideal_insertion_additions"],row["sum_actual_max_bucket_index"]).unwrap();
            summary.push(json!({"workload":workload,"strategy":row["strategy"],"width":12,"terms":terms,"terms_ratio_to_canonical":ratio,
                "ideal_insertion_additions":row["ideal_insertion_additions"],"group_window_count":windows,
                "sum_actual_max_bucket_index":row["sum_actual_max_bucket_index"]}));
        }
    }
    let manifest: Value = serde_json::from_slice(&fs::read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-clean-fft-adoption/artifacts/production-source-manifest.json").unwrap()).unwrap();
    let mut comparisons = String::new();
    for shape in ["1x2","2x2","4x2","8x2","12x2","16x2","24x2","merge-24x1"] {
        let r = &manifest["m5"][shape];
        writeln!(comparisons,"| {shape} | {:.6} | {:.0} | {:.0} | {:.3}× | {:.3}× |",r["accepted_ms"].as_f64().unwrap(),
            r["cpu_reference_ms"].as_f64().unwrap(),r["metal_reference_ms"].as_f64().unwrap(),r["cpu_speedup"].as_f64().unwrap(),r["metal_speedup"].as_f64().unwrap()).unwrap();
    }
    let analysis = json!({"status":"complete exact work screen; universal factor2 not selected; centered hypothesis remains unqualified",
        "source_audit":result["source_audit"],"census_rows":rows.len(),"tests_passed":3,
        "new_proof_exports":0,"independent_proof_ledger":12580,"production_changed":false,"adopted":false,
        "complete_window_removed_at_any_current_width":false,"summary_width12":summary,
        "accepted_performance_inherited":manifest["m5"],"goal_status":"active","goal_achieved":false,"original8_CPU10x_rows":0,
        "next":"Actual scalar census and prior implementation audit for centered magnitudes; no native advantage established. Preserve sign handling in all top-window and fused paths; do not apply whole-Fr order recoding to G2 Frobenius components."});
    fs::write(format!("{root}/analysis.json"),serde_json::to_vec_pretty(&analysis).unwrap()).unwrap();
    let report = format!("# Small-factor scalar recoding work screen\n\nThe exact BN254 screen does not support applying factor-of-two recoding universally. At width 12 it reduces nonzero digit terms by 0.74% on uniform full-width scalars, but increases them 6.27× on the small-scalar set. Simple signed centering gives a similar full-width reduction while preserving this small-scalar set. No native prover implementation or proving-time gain is claimed.\n\n[Oleksandr Hrabar's Waterloo thesis](https://uwspace.uwaterloo.ca/items/43cc12b9-cb03-42bd-a01c-4b0ed5e12403), chapter 4, describes making each scalar divisible by two using either the scalar or the subgroup-order complement, tracking a point sign, and doubling the final MSM. It also studies separate factor groups for 3/2 and 5/3/2. We read the selected chapter and related sections; this is an independent BN254 screen, not a reproduction of its BLS12-381 benchmark. The locally downloaded PDF hash is recorded; the PDF is not redistributed.\n\nThe native overlapping Booth digit function is copied verbatim and checked against the accepted source. For all widths 4..15, `ceil(255/width) == ceil(254/width)`: shortening these scalar magnitudes by one bit removes no complete window. This does not rule out smaller savings in the remaining windows.\n\nThree exact tests passed: modular recoding against independent arbitrary-precision integers and Arkworks Fr; native Booth digits against direct bit extraction and integer reconstruction at every width; and separate factor-group MSMs against an independent Arkworks G1 MSM, including identity bases. The scalar fixture contains 5,116 values: small integers, near-order values, powers of two and predecessors, and 4,096 deterministic full-width samples. The independent group test uses 139 selected values. No SDK request or new proof was needed.\n\nThe fixed census covers 32,768 uniform rejection-sampled canonical scalars and all integers 0..16,384 exclusive. Its 120 rows cover five strategies and twelve widths. These are synthetic work-count inputs, not measured proof-witness distributions.\n\n| Input set | Strategy | Nonzero terms | Terms / original | Ideal insertion additions | Group windows | Sum of maximum bucket indices |\n|---|---|---:|---:|---:|---:|---:|\n{table}\nIdeal insertion additions count terms minus distinct occupied absolute-digit destinations. They omit weighted bucket reduction. Splitting into factor groups can reduce that number by introducing more free first assignments while adding bucket tables, weighted reductions and final correction work. The separate group/window and maximum-index counts make that tradeoff visible; none is a native runtime estimate. Actual signed bucket cancellations, point exceptions, affine batching, top-window trees, grouping, scheduling and transform costs are not modeled.\n\nAt width 15, centering reduces full-width terms by only five but increases ideal insertion additions from 318,837 to 324,313 because occupancy changes. Consequently even the centered variant has no universal work-improvement claim. Factor recoding's large expansion of small odd scalars also prevents a universal adoption decision based on random full-width counts.\n\nThe next useful step is an actual-scalar census plus a history audit for signed centering, followed by native integration only if the real workload supports it. Integration must charge any sign metadata and preserve the signed top-window, deferred-Y and fused paths. Existing 127-bit G2 Frobenius components cannot independently use a whole-Fr subgroup-order recoding. This screen establishes no explanation or resolution of the C7a/Aeglos latency gap.\n\nAll 172 accepted production files and the accepted SDK hash remain exact. No lookup table, retained key plan, production allocation or source change was introduced. No CPU latency, peak RSS, minimum-RAM, portable/mobile/TEE, pressure, concurrency or AWS measurement was run. The independent proof ledger remains 12,580. The global CPU 10× target remains active and unmet for all eight shapes.\n\nThe following accepted local observations are inherited from the [FFT adoption report](../2026-10-27-clean-fft-adoption/README.md), compared with the supplied M5 references. They are not new measurements from this screen. That adoption retains its documented engineering exception: the full performance and qualified-scope gates remain false.\n\n| Shape | Accepted local ms | M5 CPU ms | M5 Metal ms | CPU ratio | Metal ratio |\n|---|---:|---:|---:|---:|---:|\n{comparisons}\nThe accepted primary peak RSS observation is 134.50 MiB. Merge 54→1 remains 161.341835 ms with the historical 1,910.1875 MiB peak RSS observation; no supplied M5 reference exists for that shape. These are not minimum RAM requirements.\n\nArtifacts include the declared design, exact model and native digit source, build/test logs, full census, source audit and summary. The reproduction script uses the pinned cached Rust dependencies; their hashes and compiler identity are recorded. No successful test or model run was repeated.\n");
    fs::write(format!("{root}/README.md"),report).unwrap();
    println!("120 census rows closed; 3 exact tests passed; production unchanged; no runtime claim");
}
